        .map((value) => normalizeFieldIdentity(value))
        .filter((value) => value.length > 0),
    );

    for (const [fieldKey, entry] of barcodeLookupByFieldKey.entries()) {
      if (targetKeys.has(fieldKey)) continue;
      if (entry.codes.includes(normalizedCode)) {
        return entry.label;
      }
