        setAllContractFields((prev) => prev.map((entry) => (
          String(entry.firestoreId || '') === boundaryId
            ? { ...entry, properties: nextProperties }
            : entry
        )));

        await updateDoc(doc(db, `users/${selectedContract.clientId}/field_boundaries/${boundaryId}`), {
