  useEffect(() => {
    const container = compactFieldPanelScrollRef.current;
    if (!container || usesDesktopFieldSidebar || !showCompactFieldPanelExpanded) {
      return;
    }

    let activePointerId: number | null = null;
    let startClientX = 0;
    let startClientY = 0;
    let startScrollLeft = 0;
    let dragging = false;
    let dragAxis: 'x' | 'y' | null = null;

    const teardownWindowListeners = () => {
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', finishPointerDrag);
      window.removeEventListener('pointercancel', finishPointerDrag);
    };

    const clearDrag = () => {
      activePointerId = null;
      startClientX = 0;
      startClientY = 0;
      startScrollLeft = container.scrollLeft;
      dragging = false;
      dragAxis = null;
      container.style.cursor = 'grab';
    };

    const onPointerDown = (event: PointerEvent) => {
      if (container.scrollWidth <= container.clientWidth) {
        return;
      }
      if (event.pointerType === 'mouse' && event.button !== 0) {
        return;
      }

      const target = event.target;
      if (target instanceof HTMLElement && target.closest('button, input, select, textarea, label, a')) {
        return;
      }

      activePointerId = event.pointerId;
      startClientX = event.clientX;
      startClientY = event.clientY;
      startScrollLeft = container.scrollLeft;
      dragging = false;
      dragAxis = null;
      container.style.cursor = 'grab';

      window.addEventListener('pointermove', onPointerMove, { passive: false });
      window.addEventListener('pointerup', finishPointerDrag);
      window.addEventListener('pointercancel', finishPointerDrag);
    };

    const onPointerMove = (event: PointerEvent) => {
      if (activePointerId !== event.pointerId) {
        return;
      }

      const deltaX = event.clientX - startClientX;
      const deltaY = event.clientY - startClientY;
      if (!dragAxis) {
        if (Math.abs(deltaX) < 6 && Math.abs(deltaY) < 6) {
          return;
        }

        dragAxis = Math.abs(deltaX) >= Math.abs(deltaY) ? 'x' : 'y';
        if (dragAxis !== 'x') {
          teardownWindowListeners();
          clearDrag();
          return;
        }
      }

      if (!dragging) {
        dragging = true;
      }

      container.style.cursor = 'grabbing';
      container.scrollLeft = startScrollLeft - deltaX;
      event.preventDefault();
      event.stopPropagation();
    };

    const finishPointerDrag = (event: PointerEvent) => {
      if (activePointerId !== event.pointerId) {
        return;
      }

      if (dragging) {
        lastCompactFieldPanelDragAtRef.current = Date.now();
      }

      teardownWindowListeners();
      clearDrag();
    };

    const onWheel = (event: WheelEvent) => {
      if (container.scrollWidth <= container.clientWidth) {
        return;
      }

      const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY)
        ? event.deltaX
        : event.deltaY;

      if (!delta) {
        return;
      }

      container.scrollLeft += delta;
      event.preventDefault();
      event.stopPropagation();
    };

    container.style.cursor = 'grab';
    container.style.touchAction = 'pan-x';
    container.addEventListener('pointerdown', onPointerDown);
    container.addEventListener('wheel', onWheel, { passive: false });

    return () => {
      teardownWindowListeners();
      container.style.cursor = '';
      container.style.touchAction = '';
      container.removeEventListener('pointerdown', onPointerDown);
      container.removeEventListener('wheel', onWheel);
    };
