    if (duration > 5000) {
      console.warn('ÔÜá´©Å  Firebase connection is slow (>5s). This may cause timeout issues.');
      console.log('­ƒÆí Consider checking your internet speed or Firebase region configuration.');
    }
  } catch (error: any) {
    const duration = Date.now() - startTime;
    console.error(`ÔØî Firebase connection test failed (${duration}ms):`, error);
    console.error('Error code:', error.code);
