    if (error.code === 'unavailable') {
      console.error('­ƒÆí Firebase is unreachable. Check internet connection.');
    } else if (error.code === 'permission-denied') {
      console.error('­ƒÆí Firebase permission denied. You may need to log in first.');
    } else if (error.message?.includes('timeout')) {
      console.error('­ƒÆí Firebase connection timeout. Network may be slow or Firebase may be under heavy load.');
    } else {
